using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
namespace LWS.TruckSports.Editor {
// Decorative copies of existing Taxi/Plowing characters. No scoring, navigation,
// impact or ragdoll framework is duplicated; interactive modes retain originals.
public static class SportsAudienceAuthoring {
 public static RuntimeAnimatorController DanceController(string folder){string directory="Assets/"+folder+"/Animation";Directory.CreateDirectory(directory);string path=directory+"/Concert audience.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(controller!=null)return controller;controller=AnimatorController.CreateAnimatorControllerAtPath(path);var dance=AssetDatabase.LoadAllAssetsAtPath("Assets/UTS_FullPack/Models/People/Animations/man/Dance_man.FBX").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));var cheer=AssetDatabase.LoadAllAssetsAtPath("Assets/UTS_FullPack/Models/People/Animations/man/cheer.FBX").OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__preview"));var state=controller.AddMotion(dance);state.name="Dance";controller.layers[0].stateMachine.defaultState=state;if(cheer!=null)controller.AddMotion(cheer).name="Cheer";return controller;}
 public static Animator Spawn(GameObject prefab,Transform parent,Vector3 position,Vector3 focus,RuntimeAnimatorController controller,float scale=.8f,bool preserveTaxiRagdoll=false){if(prefab==null)throw new ArgumentNullException(nameof(prefab));var actor=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);PrefabUtility.UnpackPrefabInstance(actor,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);actor.name="Decorative party spectator · "+prefab.name;var source=actor.GetComponent<LWS.TruckPedestrianPlowing.PlowPedestrian>();if(source!=null){foreach(var badge in new[]{source.frontBadge,source.backBadge,source.beacon})if(badge!=null)badge.gameObject.SetActive(false);if(source.distanceModel!=null)source.distanceModel.gameObject.SetActive(false);if(source.goldSymbols!=null)source.goldSymbols.SetActive(false);if(source.stopSymbols!=null)source.stopSymbols.SetActive(false);if(source.costumeNose!=null)source.costumeNose.gameObject.SetActive(false);foreach(var renderer in source.detailedRenderers)if(renderer!=null)renderer.enabled=true;if(source.presentationLOD!=null)source.presentationLOD.enabled=false;}
  if(!preserveTaxiRagdoll)foreach(var joint in actor.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(joint);if(!preserveTaxiRagdoll)foreach(var collider in actor.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);if(!preserveTaxiRagdoll)foreach(var body in actor.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(body);foreach(var nav in actor.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>(true))UnityEngine.Object.DestroyImmediate(nav);foreach(var script in actor.GetComponentsInChildren<MonoBehaviour>(true))if(script!=null&&(!preserveTaxiRagdoll||!(script is LWS.TruckTaxi.TruckTaxiPedestrian)&&!(script is LWS.TruckTaxi.ITruckTaxiPedestrianRagdoll)))UnityEngine.Object.DestroyImmediate(script);
  var animator=actor.GetComponentInChildren<Animator>();if(animator==null)throw new InvalidOperationException("Existing spectator prefab needs its authored animator: "+prefab.name);if(controller!=null&&(animator.avatar!=null&&animator.avatar.isHuman||controller.animationClips.All(c=>!c.humanMotion)))animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.CullUpdateTransforms;actor.transform.localScale=Vector3.one*scale;actor.transform.position=position;focus.y=position.y;actor.transform.LookAt(focus);return animator;
 }
}
}
